package handlers.skill.effects;

import org.l2jmobius.gameserver.entity.actor.Creature;
import org.l2jmobius.gameserver.entity.item.instance.Item;
import org.l2jmobius.gameserver.mechanics.effects.AbstractEffect;
import org.l2jmobius.gameserver.mechanics.effects.EffectType;
import org.l2jmobius.gameserver.mechanics.skill.Skill;
import org.l2jmobius.gameserver.mechanics.skill.enums.SkillFinishType;
import org.l2jmobius.gameserver.mechanics.stats.Formulas;
import org.l2jmobius.gameserver.util.StatSet;

/**
 * This class handles the removal of specific effects based on a unique skill identifier.<br>
 * It allows for targeted dispels when a {@code Skill} is executed.
 * @author Liamxroy
 */
public class DispelBySkillId extends AbstractEffect
{
	private final int _skillId;
	private final int _rate;
	
	/**
	 * Creates a new effect that dispels specific skills.<br>
	 * This constructor initializes the required skill ID and success rate.
	 * @param params A {@code StatSet} containing the configuration values.
	 */
	public DispelBySkillId(StatSet params)
	{
		_skillId = params.getInt("skillId");
		_rate = params.getInt("rate", 100);
	}
	
	/**
	 * Retrieves the type of effect associated with this instance.<br>
	 * This method returns a constant value from {@code EffectType}.
	 * @return The {@code EffectType} for this effect.
	 */
	@Override
	public EffectType getEffectType()
	{
		return EffectType.DISPEL;
	}
	
	/**
	 * Checks if the effect occurs immediately.<br>
	 * This method always returns {@code true}.
	 * @return {@code true} if the effect is instant.
	 */
	@Override
	public boolean isInstant()
	{
		return true;
	}
	
	/**
	 * Applies an instant dispel effect to a target creature.<br>
	 * This method removes specific skill effects based on the defined rate.<br>
	 * It checks if the target is alive before proceeding.
	 * @param effector The {@code Creature} performing the action.
	 * @param effected The {@code Creature} receiving the effect.
	 * @param skill The {@code Skill} being used to trigger the effect.
	 * @param item The {@code Item} associated with the skill execution.
	 */
	@Override
	public void instant(Creature effector, Creature effected, Skill skill, Item item)
	{
		if (effected.isDead())
		{
			return;
		}
		
		if ((_rate < 100) && Formulas.calcCancelSuccess(_rate, effector, effected))
		{
			return;
		}
		
		effected.stopSkillEffects(SkillFinishType.REMOVED, _skillId);
	}
}
